const payload = $input.first().json;
const tasks = Array.isArray(payload) ? payload : (Array.isArray(payload.data) ? payload.data : (Array.isArray(payload.tasks) ? payload.tasks : []));
const fa = (value) => new Intl.NumberFormat('fa-IR').format(value);
const lines = ['گزارش وظایف گالری طلا یوسفی', 'تعداد وظایف باز: ' + fa(tasks.length), ''];
if (tasks.length === 0) {
  lines.push('در حال حاضر وظیفه بازی در پاسخ API پیدا نشد. اگر انتظار وظیفه داشتی، ساختار پاسخ API را بررسی کن.');
} else {
  tasks.forEach((task, index) => {
    lines.push((index + 1) + '. ' + (task.title || 'بدون عنوان'));
    if (task.priority_score !== undefined && task.priority_score !== null) lines.push('   اولویت: ' + fa(task.priority_score));
    if (task.due_at) lines.push('   موعد: ' + task.due_at);
    else lines.push('   موعد: بدون موعد');
    lines.push('   وضعیت: ' + (task.status || 'نامشخص'));
    lines.push('');
  });
}
return [{ json: { report: lines.join('\n'), open_task_count: tasks.length, tasks } }];
